INSERT INTO zc_private.zsl_provisional_level_result(id_level,id_user,time,timeslot) SELECT $4,$5,$6::numeric/1000000,$3 FROM zc_private.zsl_tournament_level_state WHERE id_round=$1 AND $2::text IS NOT NULL AND timeslot=$3 AND id_level=$4 AND NOT closed AND to_timestamp($7::double precision/1000)<deadline ON CONFLICT(id_level,id_user) DO UPDATE SET time=excluded.time,date_updated=clock_timestamp() WHERE NOT zsl_provisional_level_result.finalised AND zsl_provisional_level_result.timeslot=excluded.timeslot AND excluded.time<zsl_provisional_level_result.time
